#include <cstdint>
#include <iostream>
#include <utility>
#include <vector>

int32_t answer = 0;

int32_t get_root(int32_t vertex, std::vector<int32_t>& parents) {
    if (parents[vertex] == vertex)
        return vertex;
    return parents[vertex] = get_root(parents[vertex], parents);
}

bool join(int32_t v1, int32_t v2, std::vector<int32_t>& parents) {
    int32_t root1 = get_root(v1, parents);
    int32_t root2 = get_root(v2, parents);

    if (root1 == root2)
        return false;

    parents[root1] = root2;
    return true;
}

void check(
    int32_t num_steps,
    const std::vector<int32_t>& choices,
    const std::vector<std::pair<int32_t, int32_t>>& edges,
    int32_t leaf_target
) {
    std::vector<int32_t> degree(num_steps + 1, 0);
    std::vector<int32_t> parents(num_steps + 1);

    for (int32_t i = 0; i <= num_steps; ++i)
        parents[i] = i;

    for (int32_t i = 0; i < num_steps; ++i) {
        const auto& edge = edges[choices[i]];
        ++degree[edge.first];
        ++degree[edge.second];

        if (!join(edge.first, edge.second, parents))
            return;
    }

    int32_t num_leaves = 0;
    for (int32_t value : degree)
        num_leaves += (value == 1);

    if (num_leaves == leaf_target)
        ++answer;
}

void enumerate(
    int32_t step,
    int32_t num_steps,
    std::vector<int32_t>& choices,
    const std::vector<std::pair<int32_t, int32_t>>& edges,
    int32_t leaf_target
) {
    if (step == num_steps) {
        check(num_steps, choices, edges, leaf_target);
        return;
    }

    int32_t start = (step == 0) ? 0 : choices[step - 1] + 1;
    for (int32_t i = start; i < static_cast<int32_t>(edges.size()); ++i) {
        choices[step] = i;
        enumerate(step + 1, num_steps, choices, edges, leaf_target);
    }
}

int main() {
    int32_t n, m, num_ends;
    std::cin >> n >> m >> num_ends;

    std::vector<std::pair<int32_t, int32_t>> edges;
    edges.reserve(m);

    for (int32_t i = 0; i < m; ++i) {
        int32_t src, dst;
        std::cin >> src >> dst;
        edges.emplace_back(src - 1, dst - 1);
    }

    std::vector<int32_t> choices(n - 1);
    enumerate(0, n - 1, choices, edges, num_ends);

    std::cout << answer;
    return 0;
}

